import AppKit
@testable import CleanerCore
import Foundation
import Testing

@Suite struct ClipboardHistoryTests {
    @Test func skipsWhatAPasswordManagerMarksAsConcealed() {
        #expect(ClipboardHistory.isConcealed([.init("org.nspasteboard.ConcealedType")]))
        #expect(ClipboardHistory.isConcealed([.string, .init("com.agilebits.onepassword")]))
        #expect(ClipboardHistory.isConcealed([.init("org.nspasteboard.TransientType")]))
        #expect(ClipboardHistory.isConcealed([.init("org.nspasteboard.AutoGeneratedType")]))
        #expect(!ClipboardHistory.isConcealed([.string, .html]))
        #expect(!ClipboardHistory.isConcealed([]))
    }

    @Test func readsNothingFromAConcealedPasteboard() {
        let pasteboard = NSPasteboard(name: .init("mc-test-\(UUID().uuidString)"))
        pasteboard.clearContents()
        pasteboard.setString("hunter2", forType: .string)
        pasteboard.setString("", forType: .init("org.nspasteboard.ConcealedType"))

        #expect(ClipboardHistory.current(pasteboard) == nil)
    }

    @Test func readsPlainTextAndNoticesAWebAddress() {
        let pasteboard = NSPasteboard(name: .init("mc-test-\(UUID().uuidString)"))
        pasteboard.clearContents()
        pasteboard.setString("just some words", forType: .string)
        #expect(ClipboardHistory.current(pasteboard)?.kind == .text)

        pasteboard.clearContents()
        pasteboard.setString("https://example.com/page", forType: .string)
        let entry = ClipboardHistory.current(pasteboard)
        #expect(entry?.kind == .url)
        #expect(entry?.text == "https://example.com/page")
    }

    @Test func ignoresAnEmptyOrBlankClipboard() {
        let pasteboard = NSPasteboard(name: .init("mc-test-\(UUID().uuidString)"))
        pasteboard.clearContents()
        #expect(ClipboardHistory.current(pasteboard) == nil)

        pasteboard.clearContents()
        pasteboard.setString("   \n\t ", forType: .string)
        #expect(ClipboardHistory.current(pasteboard) == nil)
    }

    @Test func putsTheNewestFirstAndKeepsNoDuplicates() {
        var entries: [ClipboardEntry] = []
        for text in ["one", "two", "three"] {
            entries = ClipboardHistory.adding(
                ClipboardEntry(text: text, kind: .text, source: nil), to: entries
            )
        }
        #expect(entries.map(\.text) == ["three", "two", "one"])

        // Copying something again moves it up rather than listing it twice.
        entries = ClipboardHistory.adding(ClipboardEntry(text: "one", kind: .text, source: nil), to: entries)
        #expect(entries.map(\.text) == ["one", "three", "two"])
    }

    @Test func neverGrowsPastTheLimit() {
        var entries: [ClipboardEntry] = []
        for number in 1 ... 20 {
            entries = ClipboardHistory.adding(
                ClipboardEntry(text: "\(number)", kind: .text, source: nil), to: entries, limit: 5
            )
        }
        #expect(entries.count == 5)
        #expect(entries.first?.text == "20")
        #expect(entries.last?.text == "16")
    }

    @Test func shortensALongEntryToOneLine() {
        let entry = ClipboardEntry(text: "first\nsecond\tthird", kind: .text, source: nil)
        #expect(entry.preview == "first second third")

        let long = ClipboardEntry(text: String(repeating: "x", count: 500), kind: .text, source: nil)
        #expect(long.preview.count == 201)
        #expect(long.preview.hasSuffix("…"))
    }

    @Test func keepsTheHistoryBetweenLaunchesAndForgetsItOnRequest() throws {
        let url = FileManager.default.temporaryDirectory
            .appending(path: "mc-clip-\(UUID().uuidString)/Clipboard.json")
        defer { try? FileManager.default.removeItem(at: url.deletingLastPathComponent()) }

        let entries = [ClipboardEntry(text: "kept", kind: .text, source: "Safari")]
        ClipboardHistory.save(entries, to: url)

        let loaded = ClipboardHistory.load(from: url)
        #expect(loaded.map(\.text) == ["kept"])
        #expect(loaded.first?.source == "Safari")

        ClipboardHistory.forget(at: url)
        #expect(ClipboardHistory.load(from: url).isEmpty)
    }

    @Test func isOffUntilItIsSwitchedOn() {
        // Nothing is remembered by default: this has to be asked for.
        #expect(!UserDefaults.standard.bool(forKey: ClipboardHistory.enabledKey))
    }
}
